def reference_words_string(s):
    """Obviously-correct reference: split on ',' or ' ' dropping empties."""
    res = []
    cur = []
    for ch in s:
        if ch == ',' or ch == ' ':
            if cur:
                res.append(''.join(cur))
                cur = []
        else:
            cur.append(ch)
    if cur:
        res.append(''.join(cur))
    return res


